import React from "react";
import { Container } from "react-bootstrap";
import Particle from "../Particle";
import { useInViewOnce } from "../../hooks/useInViewOnce";
import { useTranslation } from "react-i18next";
import { getShareUrl } from "../../lib/umamiApi";

function StatsEmbed() {
  const { t } = useTranslation();
  const shareUrl = getShareUrl();

  return (
    <div className="stats-embed-wrap">
      <iframe
        title={t("stats.iframe_title")}
        src={shareUrl}
        className="stats-iframe"
        loading="lazy"
      />
    </div>
  );
}

export default function Stats() {
  const { t } = useTranslation();
  const header = useInViewOnce();
  const shareUrl = getShareUrl();

  return (
    <Container fluid className="stats-section">
      <Particle />
      <Container>
        <div
          ref={header.ref}
          className={`section-card reveal stats-panel ${header.isInView ? "is-visible" : ""}`}
        >
          <div className="section-header">
            <h1 className="section-title">
              {t("stats.title_prefix")}{" "}
              <span className="purple">{t("stats.title_highlight")}</span>
            </h1>
            <p className="section-subtitle">{t("stats.subtitle")}</p>
          </div>

          {shareUrl ? (
            <StatsEmbed />
          ) : (
            <div className="stats-setup">
              <p>{t("stats.setup_share_only")}</p>
            </div>
          )}

          <p className="stats-footer">{t("stats.footer")}</p>
          <p className="stats-footer stats-footer--hint">{t("stats.path_hint")}</p>
        </div>
      </Container>
    </Container>
  );
}
